/** Voice data: tone words, a lexicon (at most 200 entries) and guidelines. */
export interface DesignSystemVoice {
  guidelines?: readonly string[];
  /**
   * At most 200 entries; keys match ^[a-z][a-z0-9-]{0,47}$ and are never __proto__, constructor or
   * prototype.
   */
  lexicon?: Readonly<Record<string, string>>;
  /** Unique items. */
  tone?: readonly string[];
}

/**
 * A Texuli design system (ADR-021, formatVersion 1): one closed JSON document a company or an agent
 * writes once and every Texuli surface follows. Data only: colors are hex or numeric oklch, lengths
 * are numbers in px, fonts and assets are same-origin relative paths or capped data URLs, and
 * nothing reaches CSS that the token contract’s css-safe checks would refuse. Generated from
 * @texuli/spec/design-system’s vocabulary by scripts/design-system-schema.ts; validateDesignSystem
 * enforces the rules the dialect cannot express.
 */
export interface DesignSystem {
  accessibility?: DesignSystemAccessibility;
  assets?: DesignSystemAssets;
  color?: DesignSystemColor;
  components?: DesignSystemComponents;
  description?: string;
  elevation?: DesignSystemElevation;
  /**
   * texuli:<theme> or an exact id@x.y.z; never a range, a URL or a path. Cycles and chains deeper
   * than 4 are refused.
   */
  extends?: string;
  format: 'texuli/design-system';
  formatVersion: 1;
  icons?: DesignSystemIcons;
  id: string;
  layout?: DesignSystemLayout;
  license?: string;
  motion?: DesignSystemMotion;
  name: string;
  owner?: string;
  shape?: DesignSystemShape;
  space?: DesignSystemSpace;
  surface?: DesignSystemSurface;
  /** Unique items. */
  tags?: readonly string[];
  typography?: DesignSystemTypography;
  /**
   * At most 16 entries; keys match ^[a-z][a-z0-9-]{0,47}$ and are never __proto__, constructor or
   * prototype.
   */
  variants?: Readonly<Record<string, DesignSystemVariant>>;
  version: string;
  voice?: DesignSystemVoice;
}
